    // Step 1: Initialize the graph and a set to store visited nodes
    List<List<Integer>> graph = new ArrayList<>();
    Set<Integer> visited = new HashSet<>();

    // Step 2: Build the graph from the edges
    for (int[] edge : edges) {
        int from = edge[0];
        int to = edge[1];
        graph.get(from).add(to);
        graph.get(to).add(from);
    }

    // Step 3: Perform a depth-first search starting from node 0
    int time = 0;
    dfs(graph, 0, visited, hasApple, time);

    // Step 4: Return the minimum time required to collect all the apples and return to node 0
    return time;
}

// Perform a depth-first search starting from node 'cur'
private void dfs(List<List<Integer>> graph, int cur, Set<Integer> visited, boolean[] hasApple, int time) {
    // Step 5: If the current node has an apple, visit it and increase the time by 1
    if (hasApple[cur]) {
        visited.add(cur);
        time++;
    }

    // Step 6: If all the apples have been visited, return as there's no need to explore further
    if (visited.size() == hasApple.length) {
        return;
    }

    // Step 7: Visit all the unvisited neighbors of the current node
    for (Integer neighbor : graph.get(cur)) {
        if (!visited.contains(neighbor)) {
            dfs(graph, neighbor, visited, hasApple, time);
        }
    }

    // Step 8: Update the minimum time required to collect all the apples and return to node 0
    time = Math.min(time, dfs(graph, 0, visited, hasApple, 0));
}
